import{_ as a,o as s,c as i,a6 as t}from"./chunks/framework.CKIbuWFA.js";const k=JSON.parse('{"title":"诊断与安全证据","description":"","frontmatter":{"title":"诊断与安全证据","docId":"developer.diagnostics","translationKey":"developer.diagnostics","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"bd492eda2007394d29d152e20ec0dba70614f06e6d29b75a3b741ed6b23f11b4","translationRevision":"a964206095c810f4a38696e84f03785331e7f03b30f9d6ad8414e129c1dbd18c","order":130},"headers":[],"relativePath":"zh/developer/diagnostics.md","filePath":"zh/developer/diagnostics.md","lastUpdated":1794611623000}'),n={name:"zh/developer/diagnostics.md"};function r(d,e,o,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="diagnostics-and-safe-evidence" tabindex="-1">诊断与安全证据 <a class="header-anchor" href="#diagnostics-and-safe-evidence" aria-label="Permalink to &quot;诊断与安全证据 {#diagnostics-and-safe-evidence}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>收集足够证据定位故障，同时避免保留账户秘密或将诊断误当成恢复。使用私有测试宿主，并了解选中了哪种<a href="./transports.html">传输</a>。应用安装一个会话收集器；状态组件导航到该收集器，不在渲染时追加条目。</p><h2 id="inspect-a-failure" tabindex="-1">检查故障 <a class="header-anchor" href="#inspect-a-failure" aria-label="Permalink to &quot;检查故障 {#inspect-a-failure}&quot;">​</a></h2><ol><li>打开失败连接、插件、同步轮次或更新器的上下文状态操作。键盘聚焦与悬停一样，会显示桌面日志操作。</li><li>按来源、严重程度和文本筛选，再查看选中条目的上下文及重复次数。</li><li>选中或筛选的条目能说明问题时，复制它们。分享前检查导出内容。</li><li>将原生健康状态与前端观察进行比较：</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>直播未连接时，探测可能被跳过。已编译的能力不代表运行时可用。桌面 UI 面板为非模态；窄屏布局使用带返回位置的 <code>/debug</code>。原生文本导出使用 <code>system.saveFile</code>，浏览器则在本地下载。</p><h2 id="understand-retention" tabindex="-1">理解保留规则 <a class="header-anchor" href="#understand-retention" aria-label="Permalink to &quot;理解保留规则 {#understand-retention}&quot;">​</a></h2><p><code>src/web/shared/diagnostics/log.ts</code> 将历史限制为 2,000 条及 2 MiB 的序列化 UTF-8。五秒内连续匹配的来源/实体事件会合并并记录重复次数。脱敏在保留前发生，包括已识别凭据及 URL 秘密位置；任意未标记的第三方秘密并不总能识别。不要向收集器添加原始设置、Cookie、RPC 参数或 HTTP 正文。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>查看器提供有界会话历史与上下文导航，不是持久审计日志。重新加载或卸载会清空内存。清空历史不会清除连接错误或修复原因。Cloud 请求 ID 可帮助关联安全失败封装；来源覆盖取决于已安装收集器，不保证捕获每个注册表或原生错误。</p><h2 id="verify-and-recover" tabindex="-1">验证与恢复 <a class="header-anchor" href="#verify-and-recover" aria-label="Permalink to &quot;验证与恢复 {#verify-and-recover}&quot;">​</a></h2><p>运行 <code>bun scripts/task.ts test web diagnostics</code>，并查看<a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/web/shared/diagnostics" target="_blank" rel="noreferrer">收集器源码</a>。使用合成值复现脱敏、淘汰及重复事件行为。遇到冲突、未知命令或凭据过期时，返回所属恢复流程。复制诊断条目只是收集证据，绝不会重试操作或批准新信任策略。</p>`,13)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
